mapper.update:
UPDATE linked_bank_account
SET last_synced_transaction_id = #{transactionId}
WHERE linked_account_id = #{linkedAccountId}
AND (last_synced_transaction_id IS NULL OR last_synced_transaction_id < #{transactionId})
